// Config: edit these values once. Every other node reads them via $('Config').first().json
// If n8n runs in Docker and Neo4j/Ollama run on the host, use host.docker.internal.
// If n8n runs directly on Windows (npm / desktop), use localhost.
return [{
  json: {
    neo4j_url: 'http://host.docker.internal:7474',
    neo4j_db: 'neo4j',
    ollama_url: 'http://host.docker.internal:11434',
    embed_model: 'nomic-embed-text',
    // Scryfall set code(s) to ingest. One set is ~250-300 cards. Space separated for several: 'fdn dsk'
    set_codes: 'fdn',
    // Paste the current TXT link from https://magic.wizards.com/en/rules
    cr_url: 'PASTE_COMPREHENSIVE_RULES_TXT_URL_HERE',
  },
}];

const input = $('Start').first().json;
const s = v => (v === undefined || v === null || String(v).trim() === '' ? null : String(v).trim());
if (!s(input.name)) throw new Error('name is required');
const params = { name: s(input.name) };
const statement = "MATCH (c:Card) WHERE toLower(c.name) CONTAINS toLower($name)
WITH c ORDER BY CASE WHEN toLower(c.name) = toLower($name) THEN 0 ELSE 1 END, size(c.name)
LIMIT 1
OPTIONAL MATCH (c)-[:HAS_KEYWORD]->(k:Keyword)
OPTIONAL MATCH (k)-[:DEFINED_BY]->(r:Rule)-[:HAS_CHUNK]->(rch:RuleChunk)
WITH c, collect(DISTINCT {keyword: k.name, rule: r.number, rule_text: left(rch.text, 900)}) AS kws
OPTIONAL MATCH (c)-[:HAS_RULINGS]->(rc:RulingChunk)
OPTIONAL MATCH (c)-[:PRINTED_IN]->(s:Set)
OPTIONAL MATCH (c)-[:LEGAL_IN]->(f:Format)
RETURN c.name AS name, c.mana_cost AS mana_cost, c.mana_value AS mana_value, c.type_line AS type_line,
       c.oracle_text AS oracle_text, c.power AS power, c.toughness AS toughness,
       [x IN kws WHERE x.keyword IS NOT NULL] AS keywords,
       rc.text AS rulings,
       collect(DISTINCT s.name) AS sets,
       collect(DISTINCT f.name) AS legal_in,
       c.scryfall_uri AS source";
return [{ json: { statements: [{ statement, parameters: params }] } }];

// Turns the Neo4j HTTP response into plain objects for the agent.
const res = $input.first().json;
if (res.errors?.length) throw new Error('Neo4j error: ' + JSON.stringify(res.errors));
const r = res.results[0];
let rows = r.data.map(d => Object.fromEntries(r.columns.map((c, i) => [c, d.row[i]])));
if (rows.length && 'score' in rows[0]) rows.sort((a, b) => b.score - a.score);
return [{ json: { count: rows.length, results: rows } }];
